public class SpecialFlowerBlock extends FlowerBlock implements EntityBlock { private final Supplier<BlockEntityType<? extends SpecialFlowerBlockEntity>> t; public SpecialFlowerBlock(Holder<MobEffect> e,int d,Properties p,Supplier<BlockEntityType<? extends SpecialFlowerBlockEntity>> t){super(e,d,p);this.t=t;} public BlockEntity newBlockEntity(BlockPos p,BlockState s){return t.get().create(p,s);} }
